/* [acct2-bro] Finest Hour port, phase 1: the logging behind the stand-ins (fh_stand_ins.c, generated by
 * tools/fh_decomp/fh_stubs.py from fh/config/stand_in_functions.tsv): every function of the game's Direct3D and
 * DirectSound.
 *
 * Each stand-in calls fh_log_call() with its arguments. What gets printed is set by the FH_LOG environment variable:
 *   0  nothing
 *   1  (the default) the first 3 calls of each function with their arguments, and every 10 seconds how many calls
 *      each function got in that time
 *   2  every call */
#pragma once
#include <stdint.h>
#include "fh_stand_ins_ids.h"

void fh_log_call(int id, const char *name, int nargs,
                 uint32_t a0, uint32_t a1, uint32_t a2, uint32_t a3, uint32_t a4, uint32_t a5);

/* For stand-ins whose real function hands back an object: a zeroed 4 KB block of guest memory, one per function, made
 * on its first call and then always the same. */
uint32_t fh_stand_in_block(int id);

/* For the Lock functions, whose callers write vertices, indices or pixels into what they get back: one shared 1 MB
 * guest buffer. What is written there is thrown away; nothing is drawn in phase 1. */
uint32_t fh_stand_in_scratch(void);

/* RenderWare's errors. RwErrorSet (0x001CFDE0) is where every RenderWare error is recorded: RwErrorSet(RwError *)
 * with RwError { pluginID, errorCode }. Its stand-in (fh/config/stand_in_functions.tsv) calls this, which does what
 * the game's own code there does (fh_log.c) and prints each different error and caller: the first time, then at 10,
 * 100, 1000 ... times, so a loop that keeps failing shows too. Nothing is printed with FH_LOG=0. Returns the
 * RwError's address, as the game's does. */
uint32_t fh_rw_error_set(uint32_t error);
